def make(slug,variant,anatomy,action,power,setting,ids,extra='',scale='Tight low-angle close-up; subject fills frame, no invented giant scale.'):
 a,e,s=ids;rs=[req('anatomy',anatomy,*a),req('setting',setting,*s)];
 if e:rs.insert(1,req('effect',power,*e))
 spec(1917,slug,variant,rs,dict(anatomy=a,power_or_deed=e,setting=s,disposition=e),f'Threat or awe through documented anatomy {a} and action {e}; no generic aura.',[extra,'Camera, dark walnut palette, weather and ordinary physical dust or spray are editorial staging.'],f'''ONE original square premium painterly cinematic Mitoloka illustration of {variant}.
ANATOMY: {anatomy} [{', '.join(a)}]
MOMENT: {action}
POWER: {power} [{', '.join(e)}]
SCALE & CAMERA: {scale}
LIGHT & WEATHER: one dominant cold moonlight source, sharp rim light, deep warm walnut shadows, natural dust or mist.
SURFACE: tactile coarse weathered surfaces, rich painterly texture, no plastic finish.
SETTING: {setting} [{', '.join(s)}]
MOOD: menacing or awe-inspiring, dangerous and imposing, never cute, calm or decorative.
HARD CONSTRAINTS: no text, pseudoinscriptions, lettering, logo, border, frame or watermark; no extra heads, limbs or fingers; no design borrowed from film, game, anime or comic; opaque full clothing for humanoids; no nudity or explicit gore; no generic glow aura, neon outline, energy ribbons or magic symbols.''')
